from itertools import combinations
F = [({'A','B'}, {'C'}), ({'C'}, {'B'})]          # R(A,B,C): AB->C, C->B
def closure(X, fds):
    X = set(X); ch = True
    while ch:
        ch = False
        for l, r in fds:
            if l <= X and not r <= X: X |= r; ch = True
    return X
def project(fds, attrs):                           # FDs of F+ that live inside attrs
    out = []
    for k in range(1, len(attrs)+1):
        for L in combinations(sorted(attrs), k):
            R = (closure(L, fds) & set(attrs)) - set(L)
            if R: out.append((set(L), R))
    return out
R1, R2 = {'A','C'}, {'B','C'}
G = project(F, R1) + project(F, R2)
print('projected FDs:', [(''.join(sorted(l)), ''.join(sorted(r))) for l, r in G])
print('AB->C preserved?', {'C'} <= closure({'A','B'}, G))
print('lossless? (common attr C is a key of R2):', closure(R1 & R2, F) >= R2)
r1 = {('a1','c1'), ('a1','c2')}                    # R1(A,C): only trivial FDs to check
r2 = {('b1','c1'), ('b1','c2')}                    # R2(B,C): C->B holds
print('C->B holds in r2:', len({c for b, c in r2}) == len(r2))
joined = {(a, b, c) for a, c in r1 for b, c2 in r2 if c == c2}   # natural join on C
ab = {}
for a, b, c in joined: ab.setdefault((a, b), set()).add(c)
print('join:', sorted(joined))
print('AB->C violated after join:', any(len(v) > 1 for v in ab.values()))
